import { Link, useLocation } from "react-router-dom";

export default function Navbar() {
  const { pathname } = useLocation();

  const linkClass = (path) =>
    `px-4 py-2 rounded-full text-sm transition-all ${
      pathname === path
        ? "bg-gray-900 text-white"
        : "text-gray-500 hover:text-gray-900"
    }`;

  return (
    <nav className="sticky top-0 z-50 bg-white border-b border-gray-200 h-16 flex items-center justify-between px-12">
      {/* Logo */}
      <Link to="/" className="flex items-center gap-2 cursor-pointer">
        <div className="w-8 h-8 bg-navy rounded-lg flex items-center justify-center text-white font-bold text-sm">
          A
        </div>
        <span className="font-semibold text-gray-900 text-base">WorkBridge DZ</span>
      </Link>

      {/* Links */}
      <div className="flex items-center gap-2">
        <Link to="/about">
          <button className={linkClass("/about")}>About</button>
        </Link>
        <Link to="/sign-in">
          <button className="px-5 py-2 rounded-full border border-gray-200 text-sm text-gray-900 hover:bg-cream transition-all">
            Sign in
          </button>
        </Link>
      </div>
    </nav>
  );
}
